insert into public.workouts (builtin_key, author_name, title, description, category, difficulty, duration_minutes, steps) values
('easy-strides', 'Track The Track', 'Easy run + relaxed strides', 'An easy run with a few smooth accelerations to finish. Keep the focus on relaxed movement, not top speed.', 'Speed', 'Beginner', 30, E'Warm up with 5 minutes of walking or easy jogging.\nRun easily for 15 minutes at a conversational pace.\nTry 4 × 15-second relaxed strides, walking until fully recovered between each. Skip the strides if you are not ready.\nCool down with 5 minutes of easy walking or jogging.'),
('sprint-form', 'Track The Track', 'Sprint form session', 'A technique-first session with short, controlled accelerations and plenty of rest.', 'Speed', 'Intermediate', 35, E'Warm up with 10 minutes of easy movement and familiar dynamic drills.\nDo 4 × 20m relaxed marching or skipping drills.\nRun 6 × 40m controlled accelerations, starting gently and building smoothly. Walk back and recover fully.\nFinish with 5–10 minutes easy. Reduce reps to keep good form.'),
('short-straights', 'Track The Track', 'Smooth straightaways', 'Short straightaway repetitions for athletes who already have a sprint training base.', 'Speed', 'Intermediate', 35, E'Warm up easily for 10 minutes, then use familiar drills.\nRun 6 × 80m fast but relaxed, not all-out.\nWalk back and take additional rest until recovered before each repetition.\nStop the set if your form becomes strained.\nCool down easily for 10 minutes.'),
('flying-builds', 'Track The Track', 'Build, float, relax', 'Practice controlled speed changes with a gradual build and an easy float.', 'Speed', 'Advanced', 40, E'Use a full 15-minute warm-up and familiar sprint drills.\nRepeat 4–6 times: gradually build for 30m, float smoothly for 20m, then slow down gently.\nTake full walking recovery, at least 2–3 minutes, between repetitions.\nChoose a pace that stays smooth and controlled; this is not a maximum-speed test.\nCool down easily for 10 minutes.'),
('minute-fartlek', 'Track The Track', 'One-minute fartlek', 'A simple time-based session: alternate a comfortably quicker minute with an easy minute.', 'Intervals', 'Beginner', 30, E'Warm up with 8 minutes of walking or easy jogging.\nAlternate 1 minute of comfortably quicker running with 1 minute of easy jogging or walking, 6 times.\nKeep the quicker sections controlled and reduce reps if needed.\nCool down easily for 10 minutes.'),
('track-200s', 'Track The Track', 'Controlled 200m repeats', 'Short track intervals with easy recovery. Aim for consistency rather than chasing a time.', 'Intervals', 'Intermediate', 40, E'Warm up easily for 10 minutes and add familiar drills.\nRun 6 × 200m at a controlled, repeatable pace.\nWalk or jog 200m between repetitions; take extra recovery if needed.\nKeep each rep similar and stop before form deteriorates.\nCool down easily for 10 minutes.'),
('track-400s', 'Track The Track', 'Steady 400m repeats', 'A repeatable interval session for experienced runners. Pick an effort you can sustain without straining.', 'Intervals', 'Intermediate', 45, E'Warm up easily for 12 minutes.\nRun 4 × 400m at a comfortably hard but controlled effort.\nRecover with 2–3 minutes of easy walking or jogging between reps.\nReduce reps or extend recovery to keep the effort manageable.\nCool down easily for 10 minutes.'),
('interval-ladder', 'Track The Track', 'The time ladder', 'Run up and back down a time-based ladder. No track or distance measurement needed.', 'Intervals', 'Advanced', 45, E'Warm up easily for 12 minutes.\nRun controlled efforts of 1, 2, 3, 2, then 1 minute.\nAfter each effort, walk or jog easily for the same amount of time.\nKeep the longer effort sustainable, not all-out. Skip a rung if needed.\nCool down easily for 10 minutes.'),
('conversational-run', 'Track The Track', 'Conversational miles', 'Keep it simple with a continuous easy run at a pace where conversation feels comfortable.', 'Endurance', 'Beginner', 30, E'Begin with 5 minutes of easy walking.\nJog easily for up to 20 minutes, using walk breaks whenever you need them.\nStay at an effort where you can speak comfortably.\nFinish with a 5-minute easy walk.'),
('steady-long', 'Track The Track', 'Easy longer run', 'A longer easy outing for runners already comfortable with this duration. Build up gradually.', 'Endurance', 'Intermediate', 50, E'Walk or jog gently for the first 5 minutes.\nContinue at an easy conversational effort for 35–40 minutes, only if that duration is already comfortable.\nUse walk breaks and choose a shorter route if needed.\nEase down for the final 5 minutes. Never jump straight to this duration from shorter runs.'),
('gentle-progression', 'Track The Track', 'Gentle progression run', 'Start easy and finish a little steadier while staying in control throughout.', 'Endurance', 'Intermediate', 35, E'Warm up easily for 10 minutes.\nRun 10 minutes at an easy conversational effort.\nIf you feel comfortable, run 5 minutes slightly steadier, without sprinting or straining.\nReturn to an easy effort for a 10-minute cool-down.'),
('tempo-blocks', 'Track The Track', 'Broken tempo blocks', 'Two sustained, controlled blocks for experienced runners, separated by easy recovery.', 'Endurance', 'Advanced', 45, E'Warm up easily for 12 minutes.\nRun 2 × 6 minutes at a comfortably hard effort that stays controlled through both blocks.\nJog or walk easily for 3 minutes between blocks.\nYou should finish with something left, not exhausted. Reduce the blocks if needed.\nCool down easily for 10 minutes.'),
('hill-intro', 'Track The Track', 'Gentle hill introduction', 'Short uphill efforts on a gentle, safe incline with an unhurried walk back down.', 'Hills', 'Beginner', 30, E'Warm up easily for 10 minutes.\nFind a gentle hill with even footing and no traffic.\nRun 4 × 15 seconds uphill at a smooth, controlled effort.\nWalk down slowly and recover fully between efforts.\nCool down easily for 10 minutes. Avoid steep hills and sprinting.'),
('hill-repeats', 'Track The Track', 'Controlled hill repeats', 'A compact uphill session for runners familiar with hill training. Keep the effort repeatable.', 'Hills', 'Intermediate', 40, E'Warm up easily for 12 minutes.\nOn a gentle hill with safe footing, run 6 × 30 seconds at a controlled effort.\nWalk down carefully and take extra rest until ready.\nKeep your posture relaxed; shorten the set if form slips.\nCool down easily for 10 minutes.'),
('rolling-route', 'Track The Track', 'Easy rolling route', 'An easy run over gentle rolling terrain. Let the pace change with the slope.', 'Hills', 'Intermediate', 35, E'Start with 5 minutes of easy walking or jogging.\nRun easily for 25 minutes on a familiar route with gentle hills.\nSlow down or walk uphill to keep a conversational effort.\nDescend carefully; do not chase speed downhill.\nFinish with 5 minutes easy.'),
('walk-jog', 'Track The Track', 'Walk–jog reset', 'A low-pressure run/walk session. Adjust the balance to how you feel today.', 'Recovery', 'Beginner', 25, E'Walk easily for 5 minutes.\nAlternate 1 minute of easy jogging with 2 minutes of walking, 5 times.\nKeep everything comfortable and walk the whole session if that feels better.\nFinish with 5 minutes of easy walking.'),
('recovery-jog', 'Track The Track', 'Short recovery jog', 'A deliberately easy outing for a day when you want gentle movement, not another hard session.', 'Recovery', 'Beginner', 20, E'Begin with 5 minutes of easy walking.\nJog gently for up to 10 minutes, adding walk breaks freely.\nStay comfortable and shorten or skip the session if tired.\nFinish with 5 minutes walking. Rest is a valid option too.'),
('easy-shakeout', 'Track The Track', 'Easy shakeout', 'A brief easy run to settle into your usual rhythm. Nothing to prove, just easy movement.', 'Race prep', 'Beginner', 20, E'Walk or jog gently for 5 minutes.\nRun easily for 10 minutes at a comfortable conversational effort.\nWalk for 5 minutes to finish.\nUse only if an easy run fits your existing race plan; choose rest instead if needed.'),
('pre-meet-strides', 'Track The Track', 'Pre-meet relaxed strides', 'A familiar, light tune-up for runners who already include strides before a meet.', 'Race prep', 'Intermediate', 25, E'Jog easily for 10 minutes.\nUse a few familiar mobility drills.\nRun 3 × 15-second relaxed strides with full walking recovery.\nFinish with 5 minutes easy.\nDo not add a new session close to a race; stick to a routine you have already tried.'),
('warmup-routine', 'Track The Track', 'Race-day warm-up outline', 'A starting outline to adapt to your event and experience. Use familiar movements only.', 'Race prep', 'Intermediate', 25, E'Walk or jog easily for 8–10 minutes.\nSpend 5 minutes on familiar dynamic mobility and event-specific drills.\nIf part of your established routine, add 2–3 short relaxed strides with full recovery.\nAllow time to settle before the start.\nAdjust the routine to your event, conditions, and what has worked for you in training.'),
('acceleration-30s', 'Track The Track', 'Controlled 30m starts', 'Practice gradually building speed over a short, clear straightaway. Smooth starts beat forcing the pace.', 'Speed', 'Beginner', 30, E'Warm up easily for 10 minutes and check the surface ahead.\nFrom a relaxed standing start, build speed gradually over about 30m.\nRepeat up to 6 times with at least 90 seconds of walking recovery, longer if needed.\nKeep every repetition controlled and skip reps if your form becomes tense.\nCool down easily for 5–10 minutes.'),
('run-walk-strides', 'Track The Track', 'Stride-and-walk circuit', 'Very short relaxed strides with long walking breaks. Use time instead of measuring a track.', 'Speed', 'Beginner', 25, E'Warm up with 8 minutes of easy walking or jogging.\nFind a flat, clear stretch with even footing.\nTry 5 × 10-second relaxed strides, not sprints.\nWalk for 90 seconds or until fully recovered between strides.\nCool down with 8 minutes of easy walking or jogging.'),
('relaxed-60s', 'Track The Track', '60m rhythm repeats', 'Short repetitions for finding a consistent, relaxed rhythm without running flat out.', 'Speed', 'Intermediate', 35, E'Warm up easily for 12 minutes and add familiar dynamic drills.\nRun 6 × 60m fast but controlled on a flat, clear straight.\nWalk back, then rest until fully recovered, roughly 2 minutes or more.\nKeep your shoulders relaxed and end the set if movement feels strained.\nCool down easily for 8–10 minutes.'),
('short-speed-sets', 'Track The Track', 'Short sprint sets', 'Two small sets of controlled accelerations for runners already used to speed sessions.', 'Speed', 'Advanced', 40, E'Warm up easily for 12–15 minutes and use familiar sprint drills.\nRun 2 sets of 3 × 50m controlled accelerations; do not go all-out.\nTake at least 2 minutes of walking recovery between repetitions and 4 minutes between sets.\nDo fewer repetitions if you cannot maintain relaxed form.\nCool down easily for 10 minutes.'),
('thirty-ninety', 'Track The Track', '30 on, 90 easy', 'A timer-friendly introduction to quicker running, with three times as much easy recovery.', 'Intervals', 'Beginner', 35, E'Warm up with 8 minutes of easy walking or jogging.\nAlternate 30 seconds of comfortably quicker running with 90 seconds of easy walking or jogging.\nRepeat up to 8 times, keeping the quicker sections controlled.\nShorten the set or walk all recoveries if needed.\nCool down easily for 8–10 minutes.'),
('two-minute-repeats', 'Track The Track', 'Two-minute repeats', 'A simple interval session you can do on a safe path using only a timer.', 'Intervals', 'Intermediate', 40, E'Warm up easily for 12 minutes.\nRun 4 × 2 minutes at a controlled effort that you can repeat without straining.\nWalk or jog easily for 3 minutes after each effort.\nSlow the quicker sections or do fewer repetitions if they stop feeling repeatable.\nCool down easily for 8 minutes.'),
('three-minute-cruise', 'Track The Track', 'Three-minute cruise intervals', 'Three sustained efforts with easy breaks. Focus on even effort rather than a particular speed.', 'Intervals', 'Intermediate', 35, E'Warm up easily for 10 minutes.\nRun 3 × 3 minutes at a steady, controlled effort.\nWalk or jog easily for 2 minutes between efforts, adding recovery if needed.\nFinish each effort feeling that you could continue a little longer.\nCool down easily for 10 minutes.'),
('smooth-600s', 'Track The Track', 'Smooth 600m repeats', 'Longer track intervals for experienced runners who want a consistent, sustainable effort.', 'Intervals', 'Advanced', 45, E'Warm up easily for 12–15 minutes.\nRun 4 × 600m at a controlled, comfortably hard effort, not a sprint.\nTake at least 3 minutes of easy walking or jogging between repetitions.\nUse fewer repetitions or a slower pace if later reps feel strained.\nCool down easily for 10 minutes.'),
('even-800s', 'Track The Track', 'Even-effort 800m repeats', 'A small set of longer intervals. Choose a pace that lets you finish the last repetition with control.', 'Intervals', 'Advanced', 45, E'Warm up easily for 12–15 minutes.\nRun 3 × 800m at a controlled effort you can sustain across the set.\nWalk or jog easily for at least 3 minutes between repetitions.\nKeep the first rep conservative; shorten the set rather than forcing a finish.\nCool down easily for 10 minutes.'),
('alternating-short-reps', 'Track The Track', 'Alternating 100m and 200m', 'Mix two short distances while keeping every effort smooth and the recovery generous.', 'Intervals', 'Intermediate', 35, E'Warm up easily for 10–12 minutes.\nComplete up to 3 rounds: 100m controlled running, easy 100m walking, then 200m controlled running.\nWalk or jog easily for 2 minutes before starting the next round.\nAdd more recovery whenever you need it; this is not a race.\nCool down easily for 10 minutes.'),
('short-steady-loop', 'Track The Track', 'Easy neighborhood loop', 'A short, familiar loop at a conversational effort. Use walking breaks without worrying about the pace.', 'Endurance', 'Beginner', 25, E'Choose a familiar, safe route with good visibility and even footing.\nWarm up with 5 minutes of easy walking.\nJog easily for up to 15 minutes, taking walk breaks when needed.\nKeep an effort that lets you speak comfortably.\nCool down with a 5-minute walk.'),
('three-one-runwalk', 'Track The Track', 'Three run, one walk', 'A run/walk session for runners already comfortable with a few minutes of easy jogging at a time.', 'Endurance', 'Beginner', 35, E'Warm up with 5 minutes of easy walking.\nAlternate 3 minutes of easy jogging with 1 minute of walking, up to 6 times.\nKeep the jogging conversational; shorten each jog or do fewer rounds if needed.\nCool down with 5 minutes of walking.\nBuild toward this duration gradually rather than starting here if you are new to running.'),
('out-and-back-easy', 'Track The Track', 'Easy out-and-back', 'An easy route with a halfway turn. Keep the return comfortable instead of trying to beat your outward time.', 'Endurance', 'Intermediate', 40, E'Warm up with 5 minutes of walking or easy jogging.\nRun out along a safe, familiar route for 15 minutes at a conversational effort.\nTurn around and return at the same comfortable effort, allowing extra time if needed.\nUse walking breaks freely and stay aware of traffic and other path users.\nCool down easily for 5 minutes.'),
('familiar-long-loop', 'Track The Track', 'Familiar longer loop', 'A relaxed longer run for experienced runners who already tolerate this amount of easy running.', 'Endurance', 'Advanced', 60, E'Choose a familiar route with options to cut it short, and plan water access for the conditions.\nStart with 5 minutes of gentle walking or jogging.\nRun easily for up to 50 minutes only if that duration is already comfortable for you.\nStay conversational, use walk breaks, and reduce the duration if tired or conditions are difficult.\nCool down easily for 5 minutes. Build to longer outings gradually.'),
('steady-five-minute-blocks', 'Track The Track', 'Five-minute steady blocks', 'Two modest steady blocks with easy running between them. No exact pace or distance needed.', 'Endurance', 'Intermediate', 30, E'Warm up easily for 10 minutes.\nRun 2 × 5 minutes at a slightly steadier but still controlled effort.\nWalk or jog easily for 2 minutes between the blocks.\nStay below a straining effort; keep both blocks easy if that feels better today.\nCool down easily for 8 minutes.'),
('comfortable-negative-split', 'Track The Track', 'Comfortable negative split', 'Finish a little steadier than you start, without turning the final section into a race.', 'Endurance', 'Intermediate', 40, E'Warm up easily for 8 minutes.\nRun 15 minutes at an easy conversational effort.\nIf you feel comfortable, run the next 10 minutes a little steadier, while keeping your breathing controlled.\nStay easy throughout or shorten the session if tired.\nCool down easily for 7 minutes.'),
('hill-walk-jog', 'Track The Track', 'Hill walk–jog mix', 'Gentle uphill jogging with plenty of walking. Keep the incline and effort manageable.', 'Hills', 'Beginner', 30, E'Warm up easily for 8–10 minutes.\nChoose a gentle, traffic-free hill with even footing.\nJog gently uphill for up to 30 seconds, then walk down carefully.\nRepeat up to 5 times, taking additional walking recovery until ready.\nCool down easily for 8–10 minutes. Walk the hills instead if jogging feels too hard.'),
('forty-five-second-hills', 'Track The Track', '45-second hill rhythm', 'A longer controlled uphill effort for runners already comfortable with shorter hill repeats.', 'Hills', 'Intermediate', 40, E'Warm up easily for 12 minutes.\nOn a gentle hill with safe footing, run 5 × 45 seconds at a controlled effort.\nWalk down carefully and recover for at least 2 minutes, or longer until ready.\nKeep the pace repeatable and shorten the set if your form deteriorates.\nCool down easily for 10 minutes.'),
('rolling-fartlek', 'Track The Track', 'Rolling-route fartlek', 'Use gentle rises as short, optional changes of effort during an otherwise easy run.', 'Hills', 'Intermediate', 40, E'Warm up easily for 10 minutes on a familiar route.\nRun easily for 20 minutes over gentle rolling terrain.\nOn up to 4 short rises, run a little more purposefully for 15–20 seconds, without sprinting.\nReturn to an easy effort for at least 2 minutes after each rise, and descend carefully.\nCool down easily for 10 minutes. Keep the whole run easy if preferred.'),
('hill-to-flat', 'Track The Track', 'Hill-to-flat transitions', 'Practice maintaining a relaxed rhythm as a gentle rise levels out. Only use a clear, familiar stretch.', 'Hills', 'Advanced', 40, E'Warm up easily for 12–15 minutes.\nFind a gentle rise that transitions onto level ground, with even footing and no traffic.\nRun smoothly uphill for about 10 seconds, then continue at a controlled effort on the flat for 10 seconds.\nRepeat up to 5 times with full walking recovery, at least 2–3 minutes.\nDo not accelerate sharply at the crest. Cool down easily for 10 minutes.'),
('easy-soft-surface', 'Track The Track', 'Easy soft-surface loop', 'An unhurried easy run on a familiar, level path. Choose safe footing over any particular surface.', 'Recovery', 'Beginner', 25, E'Warm up with 5 minutes of walking.\nChoose a familiar, even path without hidden holes, slippery patches, or traffic.\nJog gently for up to 15 minutes, using walking breaks freely.\nKeep the whole outing conversational and skip it if you need rest instead.\nCool down with 5 minutes of walking.'),
('walk-heavy-reset', 'Track The Track', 'Walk-heavy reset', 'Mostly walking with short optional jogs. A low-pressure way to get outside without chasing mileage.', 'Recovery', 'Beginner', 30, E'Walk gently for 6 minutes.\nRepeat up to 6 times: 30 seconds of easy jogging, then 2 minutes 30 seconds of walking.\nSkip any or all of the jogs if walking feels better today.\nFinish with 6 minutes of easy walking.\nChoose rest instead if you feel sore, unwell, or unusually tired.'),
('easy-treadmill', 'Track The Track', 'Easy treadmill session', 'A comfortable indoor option with no pace targets. Familiarize yourself with the controls before starting.', 'Recovery', 'Beginner', 25, E'Use a treadmill you know how to operate safely, including its stop controls.\nWalk easily for 5 minutes on a level setting.\nWalk or jog at a comfortable conversational effort for up to 15 minutes.\nSlow the belt before changing to walking; do not step off a moving belt.\nFinish with 5 minutes of easy walking and bring the belt to a stop before stepping off.'),
('no-watch-loop', 'Track The Track', 'No-watch easy loop', 'Leave pace targets behind on a short familiar route. Let comfort, not your watch, set the effort.', 'Recovery', 'Beginner', 20, E'Choose a familiar short loop you can complete comfortably in roughly 20 minutes.\nWalk gently for the first few minutes.\nJog easily through the middle, adding walking breaks whenever you want.\nKeep your breathing comfortable; do not try to match a previous time.\nWalk gently for the final few minutes, or shorten the loop if you need rest.'),
('lunchtime-reset', 'Track The Track', 'Lunchtime run/walk reset', 'A compact break for days when a short, easy outing is enough.', 'Recovery', 'Beginner', 15, E'Choose a short, safe route that is easy to cut short.\nWalk gently for 3 minutes.\nWalk or jog easily for up to 9 minutes, keeping a conversational effort.\nWalk gently for 3 minutes to finish.\nKeep it low pressure; resting instead is fine.'),
('easy-mobility-loop', 'Track The Track', 'Easy loop + gentle mobility', 'Easy movement followed by a little familiar mobility. Nothing should feel forceful or painful.', 'Recovery', 'Beginner', 25, E'Warm up with 5 minutes of easy walking.\nJog gently for up to 12 minutes, taking walking breaks whenever needed.\nWalk for 5 minutes to cool down.\nIf comfortable, spend up to 3 minutes on familiar gentle ankle or hip mobility movements.\nStay within a comfortable range; skip any movement that hurts, and choose rest if needed.'),
('warmup-rehearsal', 'Track The Track', 'Warm-up routine rehearsal', 'Try a simple warm-up during training so you know what feels comfortable before race day.', 'Race prep', 'Beginner', 30, E'Use an ordinary training day, not the day of an important race.\nWalk or jog easily for 10 minutes, then spend a few minutes on familiar mobility movements.\nContinue with 10 minutes of easy running or walking.\nCool down easily for 5 minutes.\nNote which movements and timing felt comfortable, and keep unfamiliar drills out of your race-day routine.'),
('start-line-settle', 'Track The Track', 'Start-line settle session', 'A light practice of your familiar pre-race routine, with time to settle rather than rush.', 'Race prep', 'Intermediate', 25, E'Warm up easily for 8–10 minutes.\nSpend 3 minutes on familiar mobility movements.\nIf already part of your routine, do 2 × 10-second relaxed strides with full walking recovery.\nAllow a few minutes of easy walking to practice settling your breathing before a start.\nCool down easily for 5 minutes. Keep the session light and skip new exercises close to race day.'),
('course-familiarization', 'Track The Track', 'Easy course familiarization', 'An easy look at a permitted section of a race route. Notice turns and footing without racing the course.', 'Race prep', 'Beginner', 25, E'Only use an open, permitted route; obey traffic rules and event restrictions.\nWarm up with 5 minutes of easy walking.\nWalk or jog easily for up to 15 minutes on an accessible section, noting turns, surfaces, and landmarks.\nKeep the effort conversational and do not chase race pace.\nCool down with 5 minutes of walking. A short walk is enough if you are tapering or tired.'),
('pacing-rehearsal', 'Track The Track', 'Controlled distance pacing rehearsal', 'A short pacing check for experienced distance runners, done well before race day rather than as a last-minute fitness test.', 'Race prep', 'Advanced', 35, E'Warm up easily for 12 minutes.\nRun 3 × 2 minutes at a familiar, controlled effort you intend to use in a distance race, not a sprint effort.\nWalk or jog easily for at least 2 minutes between repetitions.\nEase off if the effort feels strained and note a more sustainable starting pace.\nCool down easily for 10 minutes. Do this well before race day and keep to familiar training.')
