-- Canonical library: 50 original running sessions for solo or group training.
-- Run after workouts.sql using the SQL editor, not from the browser.
-- Repeatable: upsert by stable builtin_key to preserve IDs, likes, saves, and comments.
-- No community workouts, account data, permissions, or creation dates are changed.
on conflict (builtin_key) do update set
  author_name = excluded.author_name,
  title = excluded.title,
  description = excluded.description,
  category = excluded.category,
  difficulty = excluded.difficulty,
  duration_minutes = excluded.duration_minutes,
  steps = excluded.steps
where public.workouts.user_id is null;
